begin
   DirectVideo := FALSE;
   TextColor(14);
   SetBkColor(1);
   SetColor(14);
   cHPrint(15,177,'당신의 이름은 :');
   gotoxy(19,12); write('[]');
   s := '';
   i := 0;
   repeat begin
      inc(i);
      c := ReadKey;
      if c=#0 then begin
         c := ReadKey;
         c := #0;
         dec(i);
      end;
      if c=#8 then begin
         c := #0;
         dec(i);
      end;
      if (c<>#13) and (c<>#27) and (c<>#0) then begin
         s := s + c;
         GotoXY(19+i,12); write(c,']');
      end;
      if (c=#27) or (i>16) then begin
         i := 0; s := '';
         SetFillStyle(1,1);
         Bar(138,176,350,191);
         GotoXY(19,12); write('[]');
      end;
      if (c=#13) and (s='') then begin
         c := #0; i := 0;
      end;
   end;
   until c=#13;
   SetFillStyle(1,1);
   Bar(30,176,350,196);
   SetColor(10);
   cHPrint(15,177,'당신은 '+s+' 입니다.');
   player[1].name := s;
   SetColor(14);
   cHPrint(15,197,'당신의 성별은 : [ 남성 (M), 여성 (F) ] ');
   repeat c := UpCase(ReadKey) until (c='M') or (c='F');
   player[1].sex := male; s := '남성';
   if c='F' then begin
      player[1].sex := female;
      s := '여성';
   end;
   SetColor(10);
   Bar(118,196,350,216);
   cHPrint(15,197,'당신의 성별은 '+s+' 입니다.');
end

